   pinv=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,np.eye(6))
   bias=-.015*q; bias[1]-=.15*max(q[1]-1.6,0);bias[3]+=.03*(1.3-q[3]);bias[5]-=.1*max(q[5]-1.7,0)
   dq=pinv@err+(np.eye(7)-pinv@J)@bias
